(() => {
  const now = Date.now();
  const min = 60_000;
  localStorage.setItem('cybertools:recents', JSON.stringify([
    { id: 'hash-text', at: now - 2 * min, count: 14 },
    { id: 'base64-string-converter', at: now - 8 * min, count: 9 },
    { id: 'recipes', at: now - 12 * min, count: 11 },
    { id: 'jwt-parser', at: now - 25 * min, count: 6 },
    { id: 'ipv4-subnet-calculator', at: now - 70 * min, count: 3 },
    { id: 'to-hex', at: now - 3 * 60 * min, count: 5 },
    { id: 'url-parser', at: now - 26 * 60 * min, count: 2 },
  ]));
  localStorage.setItem('cybertools:favorites', JSON.stringify(['hash-text', 'jwt-parser', 'ipv4-subnet-calculator']));
  localStorage.setItem('cybertools:recipe', JSON.stringify([{ op: 'From Base64', args: ['A-Za-z0-9+/=', true, false] }, { op: 'Gunzip', args: [] }]));
  const settings = JSON.parse(localStorage.getItem('cybertools:settings') || '{}');
  localStorage.setItem('cybertools:settings', JSON.stringify({ ...settings, colorTheme: 'terminal', shellRailCollapsed: false }));
  localStorage.setItem('locale', 'en');
  return true;
})()

(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const until = async (test, timeout = 20000) => { for (const t0 = performance.now(); performance.now() - t0 < timeout;) { const v = test(); if (v) return v; await sleep(100); } return null; };
  const type = (el, v) => { el.value = v; el.dispatchEvent(new Event('input', { bubbles: true })); };
  const field = await until(() => document.querySelector('.io-column textarea'));
  type(field, 'H4sIAAAAAAAACvNIzcnJVyjPL8pJ0VFIK8rPVUiuTEotKsnPzylWBAC4xs7eHQAAAA==');
  await until(() => document.querySelector('.run-state--done'));
  const ops = document.querySelector('.ops-search');
  type(ops, 'hex');
  await sleep(600);
  field.blur(); ops.blur();
  return !!document.querySelector('.run-state--done');
})()

